sys_script_client.script:
function onLoad() {
    showCorrectMappingParent();
}

function showCorrectMappingParent() {

    var context = g_form.getValue('mapping_context');

    // Hide all first
    g_form.setDisplay('sub_template', false);
    g_form.setDisplay('email_template', false);

    // Show only the matching field
    if (context == 'template') {
        g_form.setDisplay('template', true);
    } else if (context == 'sub_template') {
        g_form.setDisplay('sub_template', true);
        g_form.setDisplay('template', true);
    } else if (context == 'email_template') {
        g_form.setDisplay('email_template', true);
        g_form.setDisplay('template', true);
    }
}
